export type LessonContent = { brief: string; formula: string; example: string; question: string; options: string[]; answer: number; hint: string; why: string };

export const lessonContent = {
  quantities: { brief: "Every physical measurement has a number and a unit. SI units make it possible to compare results and verify equations.", formula: "speed = distance ÷ time", example: "A distance of 500 cm is 5 m because 100 cm = 1 m.", question: "How many metres are in 250 cm?", options: ["0.25 m", "2.5 m", "25 m", "250 m"], answer: 1, hint: "Divide the number of centimetres by 100.", why: "250 ÷ 100 = 2.5 m." },
  kinematics: { brief: "Kinematics describes how position, velocity and acceleration change, without needing to explain what caused the motion.", formula: "v = u + at", example: "Starting from rest, an object accelerating at 2 m/s² for 4 s reaches a speed of 8 m/s.", question: "An object starts from rest and accelerates at 3 m/s² for 4 s. What is its final speed?", options: ["0.75 m/s", "7 m/s", "12 m/s", "24 m/s"], answer: 2, hint: "Use final speed = initial speed + acceleration × time.", why: "v = 0 + (3 × 4) = 12 m/s." },
  dynamics: { brief: "The acceleration of an object depends on the resultant force acting on it and its mass. More net force increases acceleration; more mass reduces it.", formula: "F = ma", example: "A 20 N resultant force on a 5 kg cart produces an acceleration of 4 m/s².", question: "A 20 N resultant force acts on a 5 kg object. What is its acceleration?", options: ["2 m/s²", "4 m/s²", "25 m/s²", "100 m/s²"], answer: 1, hint: "Rearrange F = ma to a = F ÷ m.", why: "a = 20 ÷ 5 = 4 m/s²." },
  forces: { brief: "Forces change motion or shape. Pressure is the force applied perpendicular to a surface divided by its area.", formula: "pressure = force ÷ area", example: "A 100 N force over 2 m² creates a pressure of 50 Pa.", question: "A force of 100 N acts over an area of 2 m². What is the pressure?", options: ["50 Pa", "100 Pa", "200 Pa", "0.02 Pa"], answer: 0, hint: "Pressure is force divided by area, not multiplied.", why: "p = 100 ÷ 2 = 50 Pa." },
  energy: { brief: "Work is energy transferred when a force acts through a distance. Energy can change form, but the total in an isolated system is conserved.", formula: "work done = force × distance", example: "Pushing with 15 N through 3 m transfers 45 J of energy.", question: "A constant force of 10 N moves an object 3 m along the force direction. How much work is done?", options: ["3 J", "13 J", "30 J", "300 J"], answer: 2, hint: "Multiply force by displacement in the direction of the force.", why: "W = 10 × 3 = 30 J." },
  deformation: { brief: "For many springs within their elastic limit, extension is proportional to the applied force. The spring constant measures stiffness.", formula: "F = kx", example: "A spring with k = 200 N/m stretches 0.05 m under a force of 10 N.", question: "A spring has k = 100 N/m and extends 0.2 m. What force is applied?", options: ["5 N", "20 N", "100 N", "500 N"], answer: 1, hint: "Use F = k × x, with extension measured in metres.", why: "F = 100 × 0.2 = 20 N." },
  waves: { brief: "Waves transfer energy. Wave speed is frequency multiplied by wavelength, while amplitude and frequency describe different wave properties.", formula: "v = fλ", example: "A 5 Hz wave with a wavelength of 2 m travels at 10 m/s.", question: "A wave has a frequency of 5 Hz and wavelength 2 m. What is its speed?", options: ["2.5 m/s", "7 m/s", "10 m/s", "25 m/s"], answer: 2, hint: "Wave speed = frequency × wavelength.", why: "v = 5 × 2 = 10 m/s." },
  superposition: { brief: "When waves overlap, their displacements add. In-phase waves reinforce each other; waves in opposite phase can cancel.", formula: "resultant displacement = y₁ + y₂", example: "Two in-phase waves each producing 2 cm displacement combine to produce 4 cm.", question: "Two identical waves each have a displacement of +2 cm at the same point. What is the resultant displacement?", options: ["0 cm", "2 cm", "4 cm", "8 cm"], answer: 2, hint: "Add the displacements algebraically.", why: "+2 cm + +2 cm = +4 cm." },
  electricity: { brief: "Current is the rate of charge flow. Potential difference transfers energy per unit charge, and resistance opposes current.", formula: "V = IR", example: "A 12 V supply across a 6 Ω resistor produces a current of 2 A.", question: "A 12 V supply is connected across a 6 Ω resistor. What is the current?", options: ["0.5 A", "2 A", "6 A", "72 A"], answer: 1, hint: "Rearrange Ohm’s law to I = V ÷ R.", why: "I = 12 ÷ 6 = 2 A." },
  circuits: { brief: "In a series circuit, current is the same through each component. In a parallel circuit, branch currents add at junctions.", formula: "I = V ÷ R", example: "Two 3 Ω resistors in series have a combined resistance of 6 Ω.", question: "Two resistors of 3 Ω and 4 Ω are connected in series. What is the total resistance?", options: ["0.75 Ω", "1 Ω", "7 Ω", "12 Ω"], answer: 2, hint: "Series resistances add together.", why: "R = 3 + 4 = 7 Ω." },
  particles: { brief: "Particle physics investigates the fundamental constituents of matter and how they interact. Use particle models to distinguish families and charges.", formula: "charge is conserved in interactions", example: "The proton carries charge +1e; an electron carries charge −1e.", question: "What electric charge does an electron carry?", options: ["+1e", "0", "−1e", "+2e"], answer: 2, hint: "An electron has the opposite charge to a proton.", why: "An electron carries one negative elementary charge (−1e)." },
  gas: { brief: "For a fixed amount of ideal gas, pressure, volume and absolute temperature are related. Use kelvin for temperature calculations.", formula: "PV = nRT", example: "At constant temperature, halving a gas volume doubles its pressure.", question: "At constant temperature, an ideal gas is compressed to half its initial volume. What happens to its pressure?", options: ["Halves", "Doubles", "Stays the same", "Becomes zero"], answer: 1, hint: "At constant temperature, pressure and volume are inversely proportional.", why: "Because PV is constant, halving V doubles P." },
  states: { brief: "Solid, liquid and gas are states of matter. Heating generally increases particle kinetic energy and can lead to phase changes.", formula: "energy transferred = mass × specific latent heat", example: "At normal atmospheric pressure, pure water boils at about 100 °C.", question: "What usually happens to particle motion when a substance is heated within one phase?", options: ["It slows down", "It stops", "Average kinetic energy increases", "Mass disappears"], answer: 2, hint: "Think about temperature and average particle kinetic energy.", why: "As temperature rises within a phase, the average kinetic energy of particles increases." },
  bonding: { brief: "Atoms form bonds by sharing or transferring electrons. Molecular shape depends on bonding pairs and lone pairs around the central atom.", formula: "H₂O = two H atoms + one O atom", example: "A water molecule consists of one oxygen atom bonded to two hydrogen atoms.", question: "How many hydrogen atoms are present in one molecule of H₂O?", options: ["1", "2", "3", "4"], answer: 1, hint: "The small subscript after H tells you how many hydrogen atoms there are.", why: "H₂O has two hydrogen atoms and one oxygen atom." },
  acids: { brief: "Acids increase the hydrogen ion concentration in water. The pH scale is logarithmic, so a change of one pH unit represents a tenfold change in [H⁺].", formula: "pH = −log₁₀[H⁺]", example: "For [H⁺] = 0.001 mol/L, the pH is 3.", question: "What is the pH of a strong acid with [H⁺] = 10⁻³ mol/L?", options: ["1", "3", "7", "11"], answer: 1, hint: "Take the negative base-10 logarithm of 10⁻³.", why: "pH = −log₁₀(10⁻³) = 3." },
  chemical: { brief: "Chemical reactions rearrange atoms while conserving them. Correct equations have the same number of each atom on both sides.", formula: "mass of reactants = mass of products", example: "2H₂ + O₂ → 2H₂O balances hydrogen and oxygen atoms.", question: "Which statement is true for a balanced chemical equation?", options: ["Atoms are destroyed", "Only products contain atoms", "Each element has equal atom counts on both sides", "Mass always doubles"], answer: 2, hint: "Count each type of atom on both sides of the equation.", why: "A balanced equation has the same number of atoms of each element on each side." },
  orbit: { brief: "Orbital motion results from gravity providing centripetal acceleration. For Keplerian orbits around the same star, longer semi-major axes have longer orbital periods.", formula: "T² ∝ a³", example: "For solar orbits measured in years and AU, an orbit with a = 4 AU has T = 8 years.", question: "For a solar orbit with semi-major axis 4 AU, approximately how many years is the orbital period?", options: ["2 years", "4 years", "8 years", "16 years"], answer: 2, hint: "Use T² = a³ for a solar orbit in years and AU.", why: "T² = 4³ = 64, so T = 8 years." },
  // Biology
  cells: { brief: "Cells are the basic units of life. Animal and plant cells share a nucleus, cytoplasm, cell membrane and mitochondria; plant cells also have a cell wall, chloroplasts and a large vacuole.", formula: "magnification = image size ÷ actual size", example: "A cell drawn 50 mm long that is really 0.05 mm long has been magnified ×1000.", question: "An image of a cell is 20 mm wide. The real cell is 0.02 mm wide. What is the magnification?", options: ["×10", "×100", "×1000", "×4000"], answer: 2, hint: "Divide the image size by the actual size, using the same units.", why: "20 ÷ 0.02 = 1000, so the magnification is ×1000." },
  membranes: { brief: "Substances cross cell membranes by diffusion, osmosis and active transport. Diffusion and osmosis follow a concentration gradient; active transport uses energy to move substances against it.", formula: "diffusion: net movement from high concentration to low concentration", example: "A plant cell placed in pure water gains water by osmosis and becomes turgid.", question: "A red blood cell is placed in a concentrated salt solution. What happens to it?", options: ["It gains water and bursts", "It loses water and shrinks", "Nothing changes", "It divides"], answer: 1, hint: "Water moves by osmosis towards the more concentrated solution.", why: "The solution outside is more concentrated, so water leaves the cell by osmosis and the cell shrinks." },
  biomolecules: { brief: "Carbohydrates, proteins and lipids are built from smaller units: sugars, amino acids, and fatty acids with glycerol. Simple chemical tests identify each one.", formula: "starch + iodine solution → blue-black", example: "Benedict's solution changes from blue to brick-red when heated with a reducing sugar.", question: "Which smaller units join together to make a protein?", options: ["Glucose", "Amino acids", "Fatty acids", "Nucleotides"], answer: 1, hint: "Proteins are long chains folded into a specific shape.", why: "Proteins are chains of amino acids." },
  enzymes: { brief: "Enzymes are protein catalysts. The substrate fits the enzyme's active site; temperature and pH change the rate of reaction, and extreme values denature the enzyme.", formula: "rate = amount of product formed ÷ time", example: "An enzyme that releases 30 cm³ of oxygen in 60 s works at a rate of 0.5 cm³/s.", question: "An enzyme reaction produces 24 cm³ of gas in 8 s. What is the rate of reaction?", options: ["0.33 cm³/s", "3 cm³/s", "16 cm³/s", "192 cm³/s"], answer: 1, hint: "Divide the volume of product by the time taken.", why: "24 ÷ 8 = 3 cm³/s." },
  photosynthesis: { brief: "Plants use light energy to make glucose from carbon dioxide and water, releasing oxygen. Light intensity, carbon dioxide concentration and temperature can each limit the rate.", formula: "6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂ (light and chlorophyll needed)", example: "Moving a lamp closer to pondweed increases the bubbles of oxygen per minute until another factor limits the rate.", question: "Which gas is released by photosynthesis?", options: ["Carbon dioxide", "Nitrogen", "Oxygen", "Hydrogen"], answer: 2, hint: "Look at the products in the equation.", why: "Photosynthesis produces glucose and releases oxygen." },
  respiration: { brief: "Respiration releases energy from glucose in every living cell. Aerobic respiration uses oxygen; anaerobic respiration releases less energy without it.", formula: "C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O", example: "During hard exercise, muscle cells also respire anaerobically and produce lactic acid.", question: "Which products are made in aerobic respiration?", options: ["Oxygen and glucose", "Carbon dioxide and water", "Lactic acid only", "Ethanol and oxygen"], answer: 1, hint: "Aerobic respiration is the reverse of the photosynthesis equation.", why: "Glucose reacts with oxygen to give carbon dioxide and water." },
  circulation: { brief: "The heart pumps blood through arteries, capillaries and veins. Cardiac output depends on the heart rate and the volume of blood pumped in each beat.", formula: "cardiac output = heart rate × stroke volume", example: "70 beats per minute × 70 cm³ per beat gives a cardiac output of 4900 cm³/min.", question: "A heart beats 60 times per minute with a stroke volume of 80 cm³. What is the cardiac output?", options: ["140 cm³/min", "480 cm³/min", "4800 cm³/min", "48 000 cm³/min"], answer: 2, hint: "Multiply heart rate by stroke volume.", why: "60 × 80 = 4800 cm³/min." },
  exchange: { brief: "Exchange surfaces such as alveoli and root hair cells have a large surface area, thin walls and a steep concentration gradient. Smaller objects have a larger surface area to volume ratio.", formula: "surface area to volume ratio = surface area ÷ volume", example: "A 1 cm cube has a surface area of 6 cm² and a volume of 1 cm³, a ratio of 6 : 1.", question: "A cube has sides of 2 cm. What is its surface area to volume ratio?", options: ["1 : 1", "3 : 1", "6 : 1", "12 : 1"], answer: 1, hint: "Surface area = 6 × side²; volume = side³.", why: "Surface area = 24 cm² and volume = 8 cm³, so the ratio is 3 : 1." },
  immunity: { brief: "Pathogens cause infectious disease. White blood cells engulf pathogens and make antibodies; vaccination prepares memory cells so a later response is faster.", formula: "antigen + matching antibody → pathogen marked for destruction", example: "After vaccination, a second exposure to the pathogen produces antibodies faster and in larger amounts.", question: "Which cells produce antibodies?", options: ["Red blood cells", "Platelets", "Lymphocytes", "Nerve cells"], answer: 2, hint: "They are a type of white blood cell.", why: "Lymphocytes make antibodies that match a pathogen's antigens." },
  homeostasis: { brief: "Organisms respond to change using nerves and hormones. Homeostasis keeps internal conditions such as blood glucose and body temperature within narrow limits by negative feedback.", formula: "stimulus → receptor → coordinator → effector → response", example: "When blood glucose rises, the pancreas releases insulin and the liver stores glucose as glycogen.", question: "Which hormone lowers blood glucose concentration?", options: ["Adrenaline", "Insulin", "Glucagon", "Oestrogen"], answer: 1, hint: "It is released by the pancreas after a meal.", why: "Insulin causes cells to take up glucose and the liver to store it as glycogen." },
  reproduction: { brief: "Mitosis makes genetically identical cells for growth and repair. Meiosis halves the chromosome number to make gametes, and fertilisation restores the full number.", formula: "cells after n mitotic divisions = 2ⁿ", example: "One cell that divides 3 times by mitosis produces 2³ = 8 cells.", question: "One cell divides by mitosis 4 times. How many cells are there?", options: ["4", "8", "16", "32"], answer: 2, hint: "The number of cells doubles at each division.", why: "2⁴ = 16 cells." },
  dna: { brief: "DNA is a double helix made of nucleotides. Base A pairs with T and C pairs with G; the base sequence of a gene codes for the amino acid sequence of a protein.", formula: "A pairs with T; C pairs with G", example: "If one strand reads ATGC, the complementary strand reads TACG.", question: "In a DNA molecule, 30% of the bases are adenine. What percentage are guanine?", options: ["20%", "30%", "40%", "70%"], answer: 0, hint: "Adenine equals thymine, and the remaining bases are shared equally between cytosine and guanine.", why: "A + T = 60%, so C + G = 40% and guanine is 20%." },
  inheritance: { brief: "Alleles are different versions of a gene. A dominant allele shows in the phenotype with one copy; a recessive allele needs two. Punnett squares predict the expected ratios.", formula: "Aa × Aa → 1 AA : 2 Aa : 1 aa", example: "Two heterozygous parents are expected to have offspring in a 3 : 1 ratio of dominant to recessive phenotypes.", question: "Two heterozygous parents (Aa × Aa) have a child. What is the probability that the child shows the recessive phenotype?", options: ["0%", "25%", "50%", "75%"], answer: 1, hint: "Only the aa genotype shows the recessive phenotype.", why: "One of the four equally likely combinations is aa, so the probability is 25%." },
  evolution: { brief: "Individuals in a population vary. Those with advantageous inherited features are more likely to survive and reproduce, so their alleles become more common over generations.", formula: "variation + selection pressure → change in allele frequency", example: "Bacteria with a resistance mutation survive an antibiotic and multiply.", question: "Why do antibiotic-resistant bacteria become more common when an antibiotic is used?", options: ["The antibiotic teaches bacteria to resist", "Resistant bacteria survive and reproduce", "All bacteria mutate on purpose", "Non-resistant bacteria reproduce faster"], answer: 1, hint: "Think about which bacteria are left alive to reproduce.", why: "Non-resistant bacteria are killed, so resistant ones survive and pass on the resistance allele." },
  ecology: { brief: "Energy enters most ecosystems as light and passes along food chains. Only a small fraction of the energy at one trophic level is transferred to the next.", formula: "efficiency = energy transferred ÷ energy available × 100%", example: "If producers hold 10 000 kJ and primary consumers gain 1000 kJ, the transfer efficiency is 10%.", question: "Primary consumers contain 2000 kJ of energy and secondary consumers gain 200 kJ. What is the transfer efficiency?", options: ["1%", "10%", "20%", "90%"], answer: 1, hint: "Divide the energy transferred by the energy available, then multiply by 100.", why: "200 ÷ 2000 × 100 = 10%." },
  classification: { brief: "Living organisms are classified into groups by shared features. The binomial system names each species by its genus and species, and biodiversity describes the variety of life in an area.", formula: "binomial name = Genus + species", example: "In Homo sapiens, Homo is the genus and sapiens is the species.", question: "In the name Panthera leo, what does “Panthera” identify?", options: ["Species", "Genus", "Kingdom", "Family"], answer: 1, hint: "The first word of a binomial name starts with a capital letter.", why: "The first word is the genus; the second is the species." },
  // Mathematics
  number: { brief: "Numbers can be written as fractions, decimals, percentages, powers and in standard form. Standard form writes a number as a × 10ⁿ, which keeps very large and very small values manageable.", formula: "a × 10ⁿ, where 1 ≤ a < 10", example: "45 000 = 4.5 × 10⁴.", question: "What is 0.0032 in standard form?", options: ["3.2 × 10⁻³", "32 × 10⁻⁴", "3.2 × 10³", "0.32 × 10⁻²"], answer: 0, hint: "Move the decimal point until there is one non-zero digit in front of it.", why: "The point moves 3 places to the right, so 0.0032 = 3.2 × 10⁻³." },
  ratio: { brief: "Ratios compare quantities, and proportion describes how one quantity changes with another. Percentage change compares a change with the original amount.", formula: "percentage change = change ÷ original × 100%", example: "A value that rises from 80 to 100 has increased by 20 ÷ 80 × 100 = 25%.", question: "A value rises from 50 to 60. What is the percentage increase?", options: ["10%", "17%", "20%", "120%"], answer: 2, hint: "Divide the change by the original value, not the new one.", why: "10 ÷ 50 × 100 = 20%." },
  algebra: { brief: "Algebra uses letters for unknown values. Solve an equation by doing the same operation to both sides; quadratic equations can be solved by factorising or with the quadratic formula.", formula: "x = (−b ± √(b² − 4ac)) ÷ 2a", example: "x² − 5x + 6 = (x − 2)(x − 3), so x = 2 or x = 3.", question: "Solve 3x + 5 = 20.", options: ["x = 3", "x = 5", "x = 8.3", "x = 15"], answer: 1, hint: "Subtract 5 from both sides, then divide by 3.", why: "3x = 15, so x = 5." },
  functions: { brief: "A function maps each input to exactly one output. Graph transformations shift, stretch or reflect a curve, and a composite function applies one function after another.", formula: "fg(x) = f(g(x))", example: "With f(x) = 2x + 1 and g(x) = x², fg(3) = f(9) = 19.", question: "f(x) = 2x + 1 and g(x) = x². What is fg(2)?", options: ["9", "10", "25", "5"], answer: 0, hint: "Work out g(2) first, then put the result into f.", why: "g(2) = 4 and f(4) = 2 × 4 + 1 = 9." },
  coordinate: { brief: "A straight line has a constant gradient. Its equation y = mx + c gives the gradient m and the y-intercept c; parallel lines have equal gradients.", formula: "gradient m = (y₂ − y₁) ÷ (x₂ − x₁)", example: "The line through (1, 2) and (3, 8) has gradient (8 − 2) ÷ (3 − 1) = 3.", question: "What is the gradient of the line through (2, 1) and (6, 9)?", options: ["0.5", "2", "4", "8"], answer: 1, hint: "Divide the change in y by the change in x.", why: "(9 − 1) ÷ (6 − 2) = 8 ÷ 4 = 2." },
  geometry: { brief: "Geometry uses angle facts, congruence, similarity and circle theorems to find unknown lengths and angles. Pythagoras' theorem links the sides of a right-angled triangle.", formula: "a² + b² = c²", example: "A right-angled triangle with shorter sides 3 cm and 4 cm has a hypotenuse of 5 cm.", question: "A right-angled triangle has shorter sides of 6 cm and 8 cm. How long is the hypotenuse?", options: ["10 cm", "14 cm", "48 cm", "100 cm"], answer: 0, hint: "Square the two shorter sides, add them, then take the square root.", why: "36 + 64 = 100 and √100 = 10 cm." },
  mensuration: { brief: "Mensuration finds perimeters, areas, surface areas and volumes. Keep units consistent: lengths in cm give areas in cm² and volumes in cm³.", formula: "volume of a prism = area of cross-section × length", example: "A cylinder of radius 2 cm and height 5 cm has volume π × 2² × 5 ≈ 62.8 cm³.", question: "A cuboid measures 2 cm × 3 cm × 5 cm. What is its volume?", options: ["10 cm³", "30 cm³", "31 cm³", "62 cm³"], answer: 1, hint: "Multiply length, width and height.", why: "2 × 3 × 5 = 30 cm³." },
  trigonometry: { brief: "Trigonometry links the angles and sides of triangles. In a right-angled triangle, sine, cosine and tangent are ratios of two sides.", formula: "sin θ = opposite ÷ hypotenuse", example: "With a hypotenuse of 10 cm and an angle of 30°, the opposite side is 10 × sin 30° = 5 cm.", question: "In a right-angled triangle the hypotenuse is 12 cm and one angle is 30°. How long is the side opposite that angle?", options: ["4 cm", "6 cm", "10.4 cm", "24 cm"], answer: 1, hint: "Use opposite = hypotenuse × sin θ, and sin 30° = 0.5.", why: "12 × 0.5 = 6 cm." },
  vectorsMath: { brief: "A vector has both size and direction. Vectors add component by component, and the magnitude of a vector comes from Pythagoras' theorem.", formula: "|a| = √(x² + y²)", example: "The vector (3, 4) has magnitude √(9 + 16) = 5.", question: "What is the magnitude of the vector (6, 8)?", options: ["7", "10", "14", "48"], answer: 1, hint: "Square each component, add them, then take the square root.", why: "√(36 + 64) = √100 = 10." },
  sequences: { brief: "A sequence follows a rule. An arithmetic sequence adds the same common difference each time; a geometric sequence multiplies by the same common ratio.", formula: "nth term of an arithmetic sequence = a + (n − 1)d", example: "For 3, 7, 11, … the 10th term is 3 + 9 × 4 = 39.", question: "What is the 20th term of the sequence 5, 8, 11, …?", options: ["57", "60", "62", "65"], answer: 2, hint: "The first term is 5 and the common difference is 3.", why: "5 + 19 × 3 = 62." },
  logs: { brief: "A logarithm is the power to which a base must be raised to give a number. Logarithms turn multiplication into addition and are used to solve equations with an unknown power.", formula: "aˣ = b means x = logₐ b", example: "log₁₀ 1000 = 3 because 10³ = 1000.", question: "What is log₂ 32?", options: ["4", "5", "6", "16"], answer: 1, hint: "Ask which power of 2 gives 32.", why: "2⁵ = 32, so log₂ 32 = 5." },
  differentiation: { brief: "Differentiation finds the gradient of a curve at a point, which is its rate of change. Stationary points occur where the derivative is zero.", formula: "d/dx (xⁿ) = nxⁿ⁻¹", example: "For y = x³, dy/dx = 3x², so the gradient at x = 2 is 12.", question: "y = 4x². What is dy/dx when x = 3?", options: ["12", "24", "36", "72"], answer: 1, hint: "Differentiate to get 8x, then substitute x = 3.", why: "dy/dx = 8x, and 8 × 3 = 24." },
  integration: { brief: "Integration reverses differentiation. A definite integral gives the area between a curve and the x-axis between two limits.", formula: "∫xⁿ dx = xⁿ⁺¹ ÷ (n + 1) + c, for n ≠ −1", example: "The integral of 3x² from 0 to 2 is 2³ − 0³ = 8.", question: "What is the value of the integral of 2x from x = 0 to x = 3?", options: ["3", "6", "9", "18"], answer: 2, hint: "The integral of 2x is x². Evaluate it at 3 and at 0.", why: "3² − 0² = 9." },
  probability: { brief: "Probability measures how likely an event is, from 0 to 1. For independent events, multiply the probabilities; for mutually exclusive events, add them.", formula: "P(A and B) = P(A) × P(B) for independent events", example: "The probability of two heads from two fair coins is ½ × ½ = ¼.", question: "A fair six-sided dice is rolled twice. What is the probability of two sixes?", options: ["1/36", "1/12", "1/6", "1/3"], answer: 0, hint: "The two rolls are independent, so multiply.", why: "1/6 × 1/6 = 1/36." },
  statistics: { brief: "Statistics summarises data. The mean, median and mode describe a typical value, while the range and standard deviation describe the spread.", formula: "mean = sum of values ÷ number of values", example: "The values 2, 4 and 9 have a mean of 15 ÷ 3 = 5.", question: "What is the mean of 3, 5, 7 and 9?", options: ["5", "6", "7", "24"], answer: 1, hint: "Add the values, then divide by how many there are.", why: "24 ÷ 4 = 6." },
} as const satisfies Record<string, LessonContent>;
export type ContentId = keyof typeof lessonContent;

export type Topic = { name: string; slug: string; content: ContentId; lab: LabId | null; section: string; /** false = the lab is related but does not cover the whole topic. */ direct: boolean };

export function slugify(value: string) {
  return value.toLowerCase().normalize("NFKD").replace(/[̀-ͯ]/g, "").replace(/['’.]/g, "").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}
